pub fn create_theme_table(lua: &Lua, context: &SongLuaCompileContext) -> mlua::Result<Table> {
    let theme = lua.create_table()?;
    let human_player_count = song_lua_human_player_count(context);
    let screen_width = context.screen_width.max(1.0);
    let screen_height = context.screen_height.max(1.0);
    set_string_method(lua, &theme, "GetCurThemeName", SONG_LUA_THEME_NAME)?;
    set_string_method(lua, &theme, "GetThemeDisplayName", SONG_LUA_THEME_NAME)?;
    set_string_method(lua, &theme, "GetCurLanguage", "en")?;
    set_string_method(
        lua,
        &theme,
        "GetCurrentThemeDirectory",
        SONG_LUA_THEME_PATH_PREFIX,
    )?;
    set_string_method(lua, &theme, "GetThemeAuthor", "")?;
    theme.set(
        "GetNumSelectableThemes",
        lua.create_function(|_, _args: IgnoredArgs| Ok(1_i64))?,
    )?;
    for method in ["DoesThemeExist", "IsThemeSelectable"] {
        theme.set(
            method,
            lua.create_function(|_, args: MultiValue| {
                let Some(Value::String(name)) = method_arg(&args, 0) else {
                    return Ok(false);
                };
                Ok(name
                    .to_str()
                    .is_ok_and(|name| name.eq_ignore_ascii_case(SONG_LUA_THEME_NAME)))
            })?,
        )?;
    }
    theme.set(
        "DoesLanguageExist",
        lua.create_function(|_, args: MultiValue| {
            let Some(Value::String(name)) = method_arg(&args, 0) else {
                return Ok(false);
            };
            Ok(name.to_str().is_ok_and(|name| {
                name.eq_ignore_ascii_case("en") || name.eq_ignore_ascii_case("english")
            }))
        })?,
    )?;
    theme.set(
        "get_theme_fallback_list",
        lua.create_function(|lua, _args: IgnoredArgs| {
            create_string_array(lua, &[SONG_LUA_THEME_NAME])
        })?,
    )?;
    theme.set(
        "RunLuaScripts",
        lua.create_function(|lua, _args: IgnoredArgs| {
            note_song_lua_side_effect(lua)?;
            Ok(())
        })?,
    )?;
    theme.set(
        "GetMetric",
        lua.create_function(move |lua, args: MultiValue| {
            let Some(group) = method_arg(&args, 0).cloned().and_then(read_string) else {
                return Ok(Value::Nil);
            };
            let Some(name) = method_arg(&args, 1).cloned().and_then(read_string) else {
                return Ok(Value::Nil);
            };
            theme_metric_value_for_human_players(
                lua,
                &group,
                &name,
                human_player_count,
                screen_width,
                screen_height,
            )
        })?,
    )?;
    theme.set(
        "GetMetricF",
        lua.create_function(move |_, args: MultiValue| {
            let Some(group) = method_arg(&args, 0).cloned().and_then(read_string) else {
                return Ok(Value::Nil);
            };
            let Some(name) = method_arg(&args, 1).cloned().and_then(read_string) else {
                return Ok(Value::Nil);
            };
            Ok(theme_metric_number_for_screen(
                &group,
                &name,
                human_player_count,
                screen_width,
                screen_height,
            )
            .map_or(Value::Nil, |value| Value::Number(f64::from(value))))
        })?,
    )?;
    theme.set(
        "GetMetricI",
        lua.create_function(move |_, args: MultiValue| {
            let Some(group) = method_arg(&args, 0).cloned().and_then(read_string) else {
                return Ok(Value::Nil);
            };
            let Some(name) = method_arg(&args, 1).cloned().and_then(read_string) else {
                return Ok(Value::Nil);
            };
            Ok(theme_metric_number_for_screen(
                &group,
                &name,
                human_player_count,
                screen_width,
                screen_height,
            )
            .map_or(Value::Nil, |value| lua_number_value(value.round())))
        })?,
    )?;
    theme.set(
        "GetMetricB",
        lua.create_function(move |lua, args: MultiValue| {
            let Some(group) = method_arg(&args, 0).cloned().and_then(read_string) else {
                return Ok(false);
            };
            let Some(name) = method_arg(&args, 1).cloned().and_then(read_string) else {
                return Ok(false);
            };
            Ok(theme_metric_bool(theme_metric_value_for_human_players(
                lua,
                &group,
                &name,
                human_player_count,
                screen_width,
                screen_height,
            )?))
        })?,
    )?;
    theme.set(
        "HasMetric",
        lua.create_function(move |lua, args: MultiValue| {
            let Some(group) = method_arg(&args, 0).cloned().and_then(read_string) else {
                return Ok(false);
            };
            let Some(name) = method_arg(&args, 1).cloned().and_then(read_string) else {
                return Ok(false);
            };
            // Native HasMetric checks the definition, without evaluating its
            // Lua expression against mutable globals.
            if crate::sl::gameplay_lead_in_seconds(&group, &name).is_some() {
                return Ok(true);
            }
            Ok(!matches!(
                theme_metric_value_for_human_players(
                    lua,
                    &group,
                    &name,
                    human_player_count,
                    screen_width,
                    screen_height,
                )?,
                Value::Nil
            ))
        })?,
    )?;
    theme.set(
        "GetMetricNamesInGroup",
        lua.create_function(|lua, args: MultiValue| {
            let Some(group) = method_arg(&args, 0).cloned().and_then(read_string) else {
                return Ok(Value::Nil);
            };
            let names = theme_metric_names(&group);
            if names.is_empty() {
                Ok(Value::Nil)
            } else {
                Ok(Value::Table(create_owned_string_array(lua, &names)?))
            }
        })?,
    )?;
    theme.set(
        "GetStringNamesInGroup",
        lua.create_function(|lua, args: MultiValue| {
            let Some(section) = method_arg(&args, 0).cloned().and_then(read_string) else {
                return Ok(Value::Nil);
            };
            let names = theme_string_names(&section);
            if names.is_empty() {
                Ok(Value::Nil)
            } else {
                Ok(Value::Table(create_owned_string_array(lua, &names)?))
            }
        })?,
    )?;
    theme.set(
        "GetPathInfoB",
        lua.create_function(|lua, args: MultiValue| {
            let group = method_arg(&args, 0)
                .cloned()
                .and_then(read_string)
                .unwrap_or_default();
            let name = method_arg(&args, 1)
                .cloned()
                .and_then(read_string)
                .unwrap_or_default();
            Ok((
                lua.create_string(theme_path("B", &group, &name))?,
                lua.create_string(&group)?,
                lua.create_string(&name)?,
            ))
        })?,
    )?;
    for (method_name, kind) in [
        ("GetPathB", "B"),
        ("GetPathF", "F"),
        ("GetPathG", "G"),
        ("GetPathO", "O"),
        ("GetPathS", "S"),
    ] {
        theme.set(
            method_name,
            lua.create_function({
                let kind = kind.to_string();
                move |lua, args: MultiValue| {
                    let group = method_arg(&args, 0)
                        .cloned()
                        .and_then(read_string)
                        .unwrap_or_default();
                    let name = method_arg(&args, 1)
                        .cloned()
                        .and_then(read_string)
                        .unwrap_or_default();
                    Ok(Value::String(
                        lua.create_string(theme_path(&kind, &group, &name))?,
                    ))
                }
            })?,
        )?;
    }
    theme.set(
        "HasString",
        lua.create_function(|_, args: MultiValue| {
            let Some(section) = method_arg(&args, 0).cloned().and_then(read_string) else {
                return Ok(false);
            };
            let Some(name) = method_arg(&args, 1).cloned().and_then(read_string) else {
                return Ok(false);
            };
            Ok(theme_has_string(&section, &name))
        })?,
    )?;
    theme.set(
        "GetString",
        lua.create_function(|lua, args: MultiValue| {
            let Some(section) = method_arg(&args, 0).cloned().and_then(read_string) else {
                return Ok(Value::String(lua.create_string("")?));
            };
            let Some(name) = method_arg(&args, 1).cloned().and_then(read_string) else {
                return Ok(Value::String(lua.create_string("")?));
            };
            Ok(Value::String(
                lua.create_string(theme_string(&section, &name))?,
            ))
        })?,
    )?;
    theme.set(
        "GetSelectableThemeNames",
        lua.create_function(|lua, _args: IgnoredArgs| {
            let names = lua.create_table()?;
            names.raw_set(1, SONG_LUA_THEME_NAME)?;
            Ok(names)
        })?,
    )?;
    for name in ["ReloadMetrics", "SetTheme"] {
        theme.set(
            name,
            lua.create_function(|lua, _args: IgnoredArgs| {
                note_song_lua_side_effect(lua)?;
                Ok(())
            })?,
        )?;
    }
    Ok(theme)
}

pub fn create_profileman_table(lua: &Lua) -> mlua::Result<Table> {
    let profileman = lua.create_table()?;
    profileman.set("__songlua_stats_prefix", "")?;
    let machine_profile = create_profile_table(lua, "Machine")?;
    let player_profiles = [
        create_profile_table(lua, "Player 1")?,
        create_profile_table(lua, "Player 2")?,
    ];
    let fallback_profile = create_profile_table(lua, "Player")?;
    let local_profile = create_profile_table(lua, "Local Profile")?;
    profileman.set(
        "GetMachineProfile",
        lua.create_function({
            let machine_profile = machine_profile.clone();
            move |_, _args: IgnoredArgs| Ok(machine_profile.clone())
        })?,
