        "GetProfileDir",
        lua.create_function(|lua, args: MultiValue| {
            let dir = match method_arg(&args, 0).and_then(profile_slot_from_value) {
                Some(SongLuaProfileSlot::Machine) => "/Save/MachineProfile/",
                _ => "",
            };
            Ok(Value::String(lua.create_string(dir)?))
        })?,
    )?;
    profileman.set(
