    )?;
    profileman.set(
        "GetNumLocalProfiles",
        lua.create_function(|_, _args: IgnoredArgs| Ok(0_i64))?,
    )?;
    profileman.set(
        "LocalProfileIDToDir",
        lua.create_function(|lua, args: MultiValue| {
            let id = method_arg(&args, 0)
                .cloned()
                .and_then(read_string)
                .unwrap_or_default();
            Ok(Value::String(
                lua.create_string(format!("/Save/LocalProfiles/{id}/"))?,
            ))
        })?,
    )?;
    profileman.set(
        "GetLocalProfileIDFromIndex",
        lua.create_function(|lua, _args: IgnoredArgs| Ok(Value::String(lua.create_string("")?)))?,
    )?;
    profileman.set(
        "GetLocalProfileFromIndex",
        lua.create_function({
            let local_profile = local_profile;
            move |_, _args: IgnoredArgs| Ok(local_profile.clone())
        })?,
    )?;
    profileman.set(
        "GetLocalProfile",
        lua.create_function(|_, _args: IgnoredArgs| Ok(Value::Nil))?,
    )?;
    profileman.set(
        "GetLocalProfileIndexFromID",
        lua.create_function(|_, _args: IgnoredArgs| Ok(-1_i64))?,
    )?;
    for method in ["GetLocalProfileIDs", "GetLocalProfileDisplayNames"] {
        profileman.set(
            method,
            lua.create_function(|lua, _args: IgnoredArgs| lua.create_table())?,
        )?;
    }
    for method in [
        "IsSongNew",
        "ProfileWasLoadedFromMemoryCard",
        "LastLoadWasTamperedOrCorrupt",
        "ProfileFromMemoryCardIsNew",
    ] {
        profileman.set(
            method,
            lua.create_function(|_, _args: IgnoredArgs| Ok(false))?,
        )?;
    }
    profileman.set(
        "GetSongNumTimesPlayed",
        lua.create_function(|_, _args: IgnoredArgs| Ok(0_i64))?,
    )?;
    profileman.set(
        "SaveMachineProfile",
        lua.create_function(|lua, _args: IgnoredArgs| {
            note_song_lua_side_effect(lua)?;
            Ok(())
        })?,
    )?;
    for method in ["SaveProfile", "SaveLocalProfile"] {
        profileman.set(
            method,
            lua.create_function(|lua, _args: IgnoredArgs| {
                note_song_lua_side_effect(lua)?;
                Ok(false)
            })?,
        )?;
    }
    profileman.set(
        "GetStatsPrefix",
        lua.create_function({
            let profileman = profileman.clone();
            move |lua, _args: IgnoredArgs| {
                let prefix = profileman
                    .get::<Option<String>>("__songlua_stats_prefix")?
                    .unwrap_or_default();
                Ok(Value::String(lua.create_string(&prefix)?))
            }
        })?,
    )?;
    profileman.set(
        "SetStatsPrefix",
        lua.create_function({
            let profileman = profileman.clone();
            move |lua, args: MultiValue| {
                let prefix = method_arg(&args, 0)
                    .cloned()
                    .and_then(read_string)
                    .unwrap_or_default();
                profileman.set("__songlua_stats_prefix", prefix)?;
                note_song_lua_side_effect(lua)?;
                Ok(profileman.clone())
            }
        })?,
    )?;
    Ok(profileman)
}

#[derive(Clone, Copy)]
enum SongLuaProfileSlot {
    Player(usize),
    Machine,
}

fn profile_slot_from_value(value: &Value) -> Option<SongLuaProfileSlot> {
    if let Some(index) = player_index_from_value(value) {
        return Some(SongLuaProfileSlot::Player(index));
    }
    match value {
        Value::Integer(2) => return Some(SongLuaProfileSlot::Machine),
        Value::Number(value) if *value == 2.0 => return Some(SongLuaProfileSlot::Machine),
        _ => {}
    }
    let text = match value {
        Value::String(text) => text.to_str().ok()?,
        _ => return None,
    };
    match text.as_ref() {
        "ProfileSlot_Player1" => Some(SongLuaProfileSlot::Player(0)),
        "ProfileSlot_Player2" => Some(SongLuaProfileSlot::Player(1)),
        "ProfileSlot_Machine" => Some(SongLuaProfileSlot::Machine),
        _ => None,
    }
}

