fn set_state_string_getter(
    lua: &Lua,
    table: &Table,
    method: &'static str,
    key: &'static str,
) -> mlua::Result<()> {
    table.set(
        method,
        lua.create_function({
            let table = table.clone();
            move |lua, (): ()| {
                let value = match table.get::<Option<crate::state_text::StateText>>(key)? {
                    Some(text) => text.into_string(lua)?,
                    None => lua.create_string("")?,
                };
                Ok(Value::String(value))
            }
        })?,
    )
}

fn set_state_string_setter(
    lua: &Lua,
    table: &Table,
    method: &'static str,
    key: &'static str,
) -> mlua::Result<()> {
    table.set(
        method,
        lua.create_function({
            let table = table.clone();
            move |lua, args: crate::state_text::StateTextArgs| {
                let value = match args.0 {
                    Some(text) => text,
                    None => lua.create_string("")?,
                };
                table.set(key, value)?;
                note_song_lua_side_effect(lua)?;
                Ok(table.clone())
            }
        })?,
    )
}

fn set_state_number_getter(
    lua: &Lua,
