pub fn create_prefsmgr_table(
    lua: &Lua,
    global_offset_seconds: f32,
    display_aspect_ratio: f32,
    display_width: i32,
    display_height: i32,
    video_renderers: &str,
    last_seen_video_driver: &str,
    event_mode: bool,
) -> mlua::Result<Table> {
    let prefsmgr = lua.create_table()?;
    let pref_store = lua.create_table()?;
    pref_store.set("EventMode", event_mode)?;
    prefsmgr.raw_set("__songlua_preference_values", pref_store.clone())?;
    let video_renderers = video_renderers.to_string();
    let last_seen_video_driver = last_seen_video_driver.to_string();
    let get_video_driver = last_seen_video_driver.clone();
    let get_video_renderers = video_renderers.clone();
    let get_pref_store = pref_store.clone();
    prefsmgr.set(
        "GetPreference",
        lua.create_function(move |lua, args: MultiValue| {
            let Some(key) = method_arg(&args, 0).cloned().and_then(read_string) else {
                return Ok(Value::Nil);
            };
            let stored = get_pref_store.get::<Value>(key.as_str())?;
            if !matches!(stored, Value::Nil) {
                return Ok(stored);
            }
            prefsmgr_default_value(
                lua,
                &key,
                global_offset_seconds,
                display_aspect_ratio,
                display_width,
                display_height,
                &get_video_renderers,
                &get_video_driver,
            )
        })?,
    )?;
    let set_pref_store = pref_store.clone();
    let prefsmgr_for_set = prefsmgr.clone();
    let set_video_renderers = video_renderers.clone();
    let set_video_driver = last_seen_video_driver.clone();
    prefsmgr.set(
        "SetPreference",
        lua.create_function(move |lua, args: MultiValue| {
            note_song_lua_side_effect(lua)?;
            let Some(key) = method_arg(&args, 0).cloned().and_then(read_string) else {
                return Ok(prefsmgr_for_set.clone());
            };
            if !matches!(
                prefsmgr_default_value(
                    lua,
                    &key,
                    global_offset_seconds,
                    display_aspect_ratio,
                    display_width,
                    display_height,
                    &set_video_renderers,
                    &set_video_driver,
                )?,
                Value::Nil
            ) {
                let value = method_arg(&args, 1).cloned().unwrap_or(Value::Nil);
                set_pref_store.set(key, value)?;
            }
            Ok(prefsmgr_for_set.clone())
        })?,
    )?;
    prefsmgr.set("PreferenceExists", {
        let exists_video_renderers = video_renderers;
        let exists_video_driver = last_seen_video_driver;
        lua.create_function(move |lua, args: MultiValue| {
            let Some(key) = method_arg(&args, 0).cloned().and_then(read_string) else {
                return Ok(false);
            };
            Ok(!matches!(
                prefsmgr_default_value(
                    lua,
                    &key,
                    global_offset_seconds,
                    display_aspect_ratio,
                    display_width,
                    display_height,
                    &exists_video_renderers,
                    &exists_video_driver,
                )?,
                Value::Nil
            ))
        })?
    })?;
    let prefsmgr_for_save = prefsmgr.clone();
    prefsmgr.set(
        "SavePreferences",
        lua.create_function(move |lua, _args: IgnoredArgs| {
            note_song_lua_side_effect(lua)?;
            Ok(prefsmgr_for_save.clone())
        })?,
    )?;
    let reset_pref_store = pref_store;
    let prefsmgr_for_reset = prefsmgr.clone();
    prefsmgr.set(
        "SetPreferenceToDefault",
        lua.create_function(move |lua, args: MultiValue| {
            note_song_lua_side_effect(lua)?;
            if let Some(key) = method_arg(&args, 0).cloned().and_then(read_string) {
                reset_pref_store.set(key, Value::Nil)?;
            }
            Ok(prefsmgr_for_reset.clone())
        })?,
    )?;
    Ok(prefsmgr)
}

pub fn prefsmgr_default_value(
    lua: &Lua,
    key: &str,
    global_offset_seconds: f32,
    display_aspect_ratio: f32,
    display_width: i32,
    display_height: i32,
    video_renderers: &str,
    last_seen_video_driver: &str,
) -> mlua::Result<Value> {
    with_ascii_lowercase(key, |lower| {
        prefsmgr_default_value_normalized(
            lua,
            lower,
            global_offset_seconds,
            display_aspect_ratio,
            display_width,
            display_height,
            video_renderers,
            last_seen_video_driver,
        )
    })
}

fn with_ascii_lowercase<R>(key: &str, use_normalized: impl FnOnce(&str) -> R) -> R {
    const STACK_KEY_BYTES: usize = 128;

    if !key.bytes().any(|byte| byte.is_ascii_uppercase()) {
        return use_normalized(key);
    }
    if key.len() <= STACK_KEY_BYTES {
        let mut normalized = [0u8; STACK_KEY_BYTES];
        normalized[..key.len()].copy_from_slice(key.as_bytes());
        normalized[..key.len()].make_ascii_lowercase();
        let normalized = std::str::from_utf8(&normalized[..key.len()])
            .expect("ASCII case folding preserves UTF-8");
        return use_normalized(normalized);
    }
    use_normalized(&key.to_ascii_lowercase())
}

fn prefsmgr_default_value_normalized(
    lua: &Lua,
    lower: &str,
    global_offset_seconds: f32,
    display_aspect_ratio: f32,
    display_width: i32,
    display_height: i32,
    video_renderers: &str,
    last_seen_video_driver: &str,
) -> mlua::Result<Value> {
    if lower == "globaloffsetseconds" {
        Ok(Value::Number(f64::from(global_offset_seconds)))
    } else if lower == "displayaspectratio" {
        Ok(Value::Number(f64::from(display_aspect_ratio)))
    } else if lower == "displaywidth" {
        Ok(Value::Integer(display_width.into()))
    } else if lower == "displayheight" {
        Ok(Value::Integer(display_height.into()))
    } else if lower == "videorenderers" {
        Ok(Value::String(lua.create_string(video_renderers)?))
    } else if lower == "lastseenvideodriver" {
        Ok(Value::String(lua.create_string(last_seen_video_driver)?))
    } else if lower == "eventmode" {
        Ok(Value::Boolean(true))
    } else if lower == "visualdelayseconds" {
