        Ok(Value::String(lua.create_string(value)?))
    } else if lower == "theme" {
        Ok(Value::String(lua.create_string(SONG_LUA_THEME_NAME)?))
    } else if lower.starts_with("defaultlocalprofileid") {
        Ok(Value::String(lua.create_string("")?))
    } else {
        Ok(Value::Nil)
    }
}

