pub fn create_timing_table(
    lua: &Lua,
    display_bpms: [f32; 2],
    timing: Option<&deadsync_rules::timing::TimingData>,
) -> mlua::Result<Table> {
    use deadsync_rules::timing::{TimingData, TimingSegments};
    let timing = timing.cloned().unwrap_or_else(|| {
        TimingData::from_segments(
            0.0,
            0.0,
            &TimingSegments {
                bpms: vec![(0.0, display_bpms[0].max(0.001))],
                ..TimingSegments::default()
            },
            &[],
        )
    });
    let points: std::sync::Arc<[(f32, f32)]> = timing.bpm_segments().collect();
    let range = points
        .iter()
        .fold([f32::MAX, 0.0_f32], |[min, max], &(_, bpm)| {
            [min.min(bpm), max.max(bpm)]
        });
    let table = lua.create_table()?;
    table.set(
        "GetActualBPM",
        lua.create_function(move |lua, _: MultiValue| lua.create_sequence_from(range))?,
    )?;
    table.set(
        "GetBPMs",
        lua.create_function({
            let points = points.clone();
            move |lua, _: MultiValue| lua.create_sequence_from(points.iter().map(|&(_, bpm)| bpm))
        })?,
    )?;
    table.set(
        "GetBPMsAndTimes",
        lua.create_function(move |lua, args: MultiValue| {
            // LunaTimingData uses Lua truthiness: zero and empty strings are true.
            let numeric = !matches!(
                method_arg(&args, 0),
                None | Some(Value::Nil | Value::Boolean(false))
            );
            let out = lua.create_table()?;
            for (index, &(beat, bpm)) in points.iter().enumerate() {
                if numeric {
                    out.raw_set(index + 1, lua.create_sequence_from([beat, bpm])?)?;
                } else {
                    out.raw_set(index + 1, format!("{beat:.6}={bpm:.6}"))?;
                }
            }
            Ok(out)
        })?,
    )?;
    let changes = timing.has_bpm_changes();
    table.set(
        "HasBPMChanges",
        lua.create_function(move |_, _: MultiValue| Ok(changes))?,
    )?;
    for method in [
        "GetBPMAtBeat",
        "GetElapsedTimeFromBeat",
        "GetBeatFromElapsedTime",
    ] {
        let timing = timing.clone();
        table.set(
            method,
            lua.create_function(move |lua, args: MultiValue| {
                let value = method_arg(&args, 0)
                    .cloned()
                    .and_then(read_f32)
                    .ok_or_else(|| mlua::Error::runtime(format!("{method} requires a number")))?;
                Ok(match method {
                    // TimingData::GetBPMAtBeat selects by the rounded note row.
                    "GetBPMAtBeat" => timing.get_bpm_for_beat(
                        deadsync_core::timing::note_row_to_beat(
                            deadsync_core::timing::beat_to_note_row(value),
                        ),
                    ),
                    // Lua exposes ITGmania's float timing traversal. The
                    // integer timeline remains the note-judgment clock.
                    "GetElapsedTimeFromBeat" => timing.get_song_time_for_beat(value,
                        crate::song_tables::current_music_rate(lua)?),
                    _ => timing.get_song_position_with_rate(value,
                        crate::song_tables::current_music_rate(lua)?).beat,
                })
            })?,
        )?;
    }
    Ok(table)
}

pub fn create_style_table(lua: &Lua, style_name: &str) -> mlua::Result<Table> {
    let table = lua.create_table()?;
    table.raw_set("__songlua_style_key", style_name)?;
    let style = crate::song_lua_style_info(style_name);
    let style_name_for_get = style.name.to_string();
    table.set(
        "GetName",
        lua.create_function(move |lua, _args: IgnoredArgs| {
            Ok(Value::String(lua.create_string(&style_name_for_get)?))
        })?,
    )?;
    set_string_method(lua, &table, "GetStepsType", style.steps_type)?;
    set_string_method(lua, &table, "GetStyleType", style.style_type)?;
    table.set(
        "ColumnsPerPlayer",
        lua.create_function(move |_, _args: IgnoredArgs| Ok(style.columns as i64))?,
    )?;
    table.set(
        "GetWidth",
        lua.create_function(move |_, _args: IgnoredArgs| Ok(style.width))?,
    )?;
    table.set(
        "GetColumnInfo",
        lua.create_function(move |lua, args: MultiValue| {
            let index = method_arg(&args, 1)
                .cloned()
                .and_then(read_i32_value)
                .unwrap_or(1)
                .clamp(1, style.columns as i32) as usize
                - 1;
            let info = lua.create_table()?;
            info.set("Name", crate::song_lua_style_column_name(index))?;
            info.set("Track", index as i64)?;
            info.set("XOffset", crate::song_lua_style_column_x(style.name, index))?;
            Ok(info)
        })?,
    )?;
    Ok(table)
}

pub fn display_bpms_for_args(
    args: &MultiValue,
    fallback: [f32; 2],
    default_rate: f32,
) -> mlua::Result<([f32; 2], f32)> {
    let rate = args
        .get(2)
        .cloned()
        .and_then(read_f32)
        .unwrap_or(default_rate)
        .max(f32::EPSILON);
    let bpms = args
        .get(1)
        .and_then(display_bpms_from_value)
        .transpose()?
        .unwrap_or(fallback);
    Ok(([bpms[0] * rate, bpms[1] * rate], rate))
}

pub fn create_split_table(lua: &Lua, text: &str, separator: &str) -> mlua::Result<Table> {
    if separator.is_empty() {
        let table = lua.create_table_with_capacity(text.chars().count().max(1), 0)?;
        if text.is_empty() {
            table.raw_set(1, "")?;
        } else {
            let mut encoded = [0; 4];
            for (idx, value) in text.chars().enumerate() {
                table.raw_set(idx + 1, &*value.encode_utf8(&mut encoded))?;
            }
        }
        return Ok(table);
    }
    let capacity = if separator.len() == 1 {
        // ASCII separators occupy one byte. memchr's count scans them in bulk,
        // avoiding a second generic split traversal for long token lists.
        memchr::memchr_iter(separator.as_bytes()[0], text.as_bytes()).count() + 1
    } else {
        text.split(separator).count()
    };
    let table = lua.create_table_with_capacity(capacity, 0)?;
    for (idx, value) in text.split(separator).enumerate() {
        table.raw_set(idx + 1, value)?;
    }
    Ok(table)
}

pub fn create_range_table(lua: &Lua, args: &MultiValue) -> mlua::Result<Value> {
    let Some(mut start) = args.front().cloned().and_then(read_f32) else {
        return Ok(Value::Nil);
    };
    let stop = if let Some(stop) = args.get(1).cloned().and_then(read_f32) {
        stop
    } else {
        let stop = start;
        start = 1.0;
        stop
    };
    let mut step = args.get(2).cloned().and_then(read_f32).unwrap_or(1.0);
    if step.abs() <= f32::EPSILON {
        return Ok(Value::Table(lua.create_table()?));
    }
    if step > 0.0 && start > stop {
        step = -step;
    }
    if step < 0.0 && start < stop {
        return Ok(Value::Table(lua.create_table()?));
    }

    // This estimates storage only. Repeated f32 addition below still decides
    // the exact values/count, including stalled increments and the 10,000 cap.
    let capacity = if start.is_finite() && stop.is_finite() && step.is_finite() {
        (((f64::from(stop) - f64::from(start)) / f64::from(step)).floor() + 1.0)
            .clamp(0.0, 10_000.0) as usize
    } else {
        0
    };
    let table = lua.create_table_with_capacity(capacity, 0)?;
    let mut index = 1;
    let mut value = start;
    while (step > 0.0 && value <= stop + f32::EPSILON)
        || (step < 0.0 && value >= stop - f32::EPSILON)
    {
        table.raw_set(index, lua_number_value(value))?;
        index += 1;
        value += step;
        if index > 10_000 {
            break;
        }
    }
    Ok(Value::Table(table))
}

pub fn stringify_lua_table(lua: &Lua, args: &MultiValue) -> mlua::Result<Value> {
    let Some(Value::Table(table)) = args.front() else {
        return Ok(Value::Nil);
    };
    let form = args.get(1).cloned().and_then(read_string);
    let format = lua
        .globals()
        .get::<Table>("string")?
        .get::<Function>("format")?;
    let out = lua.create_table()?;
    for (idx, value) in table.sequence_values::<Value>().enumerate() {
        let value = value?;
        let value = if let Some(form) = form.as_deref()
            && matches!(value, Value::Integer(_) | Value::Number(_))
        {
            format.call::<Value>((form, value))?
        } else {
            value
        };
        if let Value::String(text) = value {
            // Preserve UTF-8 validation while transferring the existing Lua
            // string instead of copying it through an owned Rust String.
            text.to_str()?;
            out.raw_set(idx + 1, text)?;
        } else {
            out.raw_set(idx + 1, lua_text_value(value)?)?;
        }
    }
    Ok(Value::Table(out))
}

pub fn map_lua_table(lua: &Lua, function: &Function, table: &Table) -> mlua::Result<Table> {
    let out = lua.create_table()?;
    for (idx, value) in table.sequence_values::<Value>().enumerate() {
        out.raw_set(idx + 1, function.call::<Value>(value?)?)?;
    }
    Ok(out)
}

// Separate compact key sets preserve Lua's non-transitive mixed-number
// comparisons without storing a large tagged key for every numeric entry.
struct DeduplicateIndex {
    booleans: u8,
    integers: std::collections::HashSet<mlua::Integer>,
    numbers: std::collections::HashSet<u64>,
    integer_numbers: Option<std::collections::HashSet<u64>>,
    strings: std::collections::HashSet<mlua::LuaString>,
    tables: std::collections::HashSet<usize>,
}

impl DeduplicateIndex {
    fn from_prefix(prefix: &[Value]) -> Self {
        let (mut integers, mut numbers, mut strings, mut tables) = (0, 0, 0, 0);
        for value in prefix {
            match value {
                Value::Integer(_) => integers += 1,
                Value::Number(value) if !value.is_nan() => numbers += 1,
                Value::String(value) if value.to_str().is_ok() => strings += 1,
                Value::Table(_) => tables += 1,
                _ => {}
            }
        }
        let mut index = Self {
            booleans: 0,
            integers: std::collections::HashSet::with_capacity(integers),
            numbers: std::collections::HashSet::with_capacity(numbers),
            // Integer-only input needs no rounded projection. If the prefix
            // already contains floats, reserve it once alongside exact keys.
            integer_numbers: (numbers != 0)
                .then(|| std::collections::HashSet::with_capacity(integers)),
            strings: std::collections::HashSet::with_capacity(strings),
            tables: std::collections::HashSet::with_capacity(tables),
        };
        for value in prefix {
            index.insert(value);
        }
        index
    }

    fn insert(&mut self, value: &Value) -> bool {
        fn number_bits(value: f64) -> u64 {
            if value == 0.0 { 0 } else { value.to_bits() }
        }
        match value {
            Value::Boolean(value) => {
                let mask = 1 << u8::from(*value);
                let new = self.booleans & mask == 0;
                self.booleans |= mask;
                new
            }
            Value::Integer(value) => {
                let bits = number_bits(*value as f64);
                if self.numbers.contains(&bits) || !self.integers.insert(*value) {
                    return false;
                }
                if let Some(integer_numbers) = &mut self.integer_numbers {
                    integer_numbers.insert(bits);
                }
                true
            }
            Value::Number(value) if !value.is_nan() => {
                let bits = number_bits(*value);
                // Include every accepted integer when a float first arrives,
                // including distinct integers that round to the same float.
                let integer_numbers = self.integer_numbers.get_or_insert_with(|| {
                    self.integers
                        .iter()
                        .map(|value| number_bits(*value as f64))
                        .collect()
                });
                !integer_numbers.contains(&bits) && self.numbers.insert(bits)
            }
            Value::String(value) if value.to_str().is_ok() => self.strings.insert(value.clone()),
            Value::Table(value) => self.tables.insert(value.to_pointer() as usize),
            // These values never compare equal under lua_values_equal.
            _ => true,
        }
    }
}

// Keep the larger index frame out of the short-list path. This is called once
// after accepting the 33rd value; the remaining loop needs no mode check.
#[inline(never)]
fn finish_indexed_deduplication(
    out: &Table,
    mut out_index: usize,
    prefix: Vec<Value>,
    first: Value,
    remaining: impl Iterator<Item = mlua::Result<Value>>,
) -> mlua::Result<()> {
    let mut index = DeduplicateIndex::from_prefix(&prefix);
    drop(prefix);
    index.insert(&first);
    out.raw_set(out_index, first)?;
    out_index += 1;
    for value in remaining {
        let value = value?;
        if index.insert(&value) {
            out.raw_set(out_index, value)?;
            out_index += 1;
        }
    }
    Ok(())
}

pub fn deduplicate_lua_table(lua: &Lua, table: &Table) -> mlua::Result<Table> {
    let out = lua.create_table()?;
    let mut seen = Vec::new();
    let mut out_index = 1;
    let mut values = table.sequence_values::<Value>();
    for value in values.by_ref() {
        let value = value?;
        if seen.iter().any(|seen| lua_values_equal(seen, &value)) {
            continue;
        }
        if seen.len() == 32 && table.raw_len() >= 128 {
            finish_indexed_deduplication(&out, out_index, seen, value, values)?;
            return Ok(out);
        }
        seen.push(value.clone());
        out.raw_set(out_index, value)?;
        out_index += 1;
    }
    Ok(out)
}

pub fn rotate_lua_table(lua: &Lua, args: &MultiValue, left: bool) -> mlua::Result<Table> {
    let Some(Value::Table(input)) = args.front() else {
        return lua.create_table();
    };
    let len = input.raw_len();
    if len == 0 {
        return lua.create_table();
    }
    let shift = i64::from(args.get(1).cloned().and_then(read_i32_value).unwrap_or(1));
    let len_i64 = len as i64;
    let out = lua.create_table()?;
    for index in 1..=len_i64 {
        let source = if left {
            (index + shift - 1).rem_euclid(len_i64) + 1
        } else {
            (index - shift - 1).rem_euclid(len_i64) + 1
        };
        out.raw_set(index, input.raw_get::<Value>(source)?)?;
    }
    Ok(out)
}

